return ['domain'=>'tranzly','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de_DE','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'Mehrsprachiges WordPress, ein Beitrag pro Sprache: verknüpfte Übersetzungen von Beiträgen, Seiten, Kategorien, Medientexten, Widgets und dem Website-Titel, wobei Ihre alten Tranzly-Übersetzungen importiert wurden.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'KI-Anbieter','The makers of ChatGPT. A good all-rounder.'=>'Die Entwickler von ChatGPT. Ein guter Allrounder.','The makers of Claude. Strong at writing and careful reasoning.'=>'Die Entwickler von Claude. Stark im Schreiben und sorgfältig beim Schlussfolgern.','Google\'s Gemini models. Fast and inexpensive.'=>'Die Modelle Gemini von Google. Schnell und kostengünstig.','A European AI company with fast, inexpensive models.'=>'Ein europäisches KI-Unternehmen mit schnellen, kostengünstigen Modellen.','Low-cost models that are good at writing and code.'=>'Günstige Modelle, die gut im Schreiben und Programmieren sind.','One key for models from many different providers.'=>'Ein Schlüssel für Modelle verschiedener Anbieter.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Jeder Dienst, der wie die API von OpenAI funktioniert, einschließlich eines Modells, das auf Ihrem eigenen Computer oder Server läuft.','General (used when nothing more specific is set)'=>'Allgemein (wird verwendet, wenn nichts Spezifischeres festgelegt ist)','Writing and rewriting'=>'Schreiben und Umschreiben','Translation'=>'Übersetzung','Code and CSS'=>'Code und CSS','Sorry, you are not allowed to access this page.'=>'Entschuldigung, Sie haben keine Berechtigung, auf diese Seite zuzugreifen.','These settings are shared by every plugin that uses them: %s.'=>'Diese Einstellungen werden von jedem Plugin gemeinsam genutzt, das sie verwendet: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Ihre Schlüssel werden in der Datenbank dieser Website verschlüsselt und ausschließlich an den von Ihnen gewählten Anbieter gesendet – niemals an uns.','Step 1 of 2: choose an AI provider'=>'Schritt 1 von 2: KI-Anbieter auswählen','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Sie verwenden Ihren eigenen Schlüssel, sodass Sie den Anbieter direkt für das bezahlen, was Sie nutzen. Unsicher? Jede dieser Optionen funktioniert gut; Sie können später weitere hinzufügen.','Next'=>'Weiter','Step 2 of 2: connect %s'=>'Schritt 2 von 2: %s verbinden','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Geben Sie die Adresse Ihres OpenAI-kompatiblen Dienstes ein, die auf /v1 endet. Ein Schlüssel ist nur erforderlich, wenn der Dienst danach fragt.','Open %s and sign in (or create a free account).'=>'Öffnen Sie %s und melden Sie sich an (oder erstellen Sie ein kostenloses Konto).','the %s API keys page'=>'die %s API-Schlüssel-Seite','Create a new key and copy it.'=>'Erstellen Sie einen neuen Schlüssel und kopieren Sie ihn.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Fügen Sie es unten ein und klicken Sie auf „Speichern und testen“. Wir senden eine winzige Anfrage, um zu prüfen, ob es funktioniert.','Most providers need a little credit on the account before a key works: %s.'=>'Die meisten Anbieter benötigen ein kleines Guthaben auf dem Konto, bevor ein Schlüssel funktioniert: %s.','add credit'=>'Guthaben hinzufügen','← Choose a different provider'=>'← Anderen Anbieter auswählen','Address'=>'Adresse','Saved key ends in …%s — paste a new one to replace it'=>'Gespeicherter Schlüssel endet auf …%s – fügen Sie einen neuen ein, um ihn zu ersetzen','Key (optional)'=>'Schlüssel (optional)','API key'=>'API-Schlüssel','Save and test'=>'Speichern und testen','Providers'=>'Provider','Provider'=>'Anbieter','Status'=>'Status','Key'=>'Schlüssel','Get a key'=>'Schlüssel erhalten','Test'=>'Test','Remove'=>'Entfernen','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Gespeichert mit einer neueren Plugin-Version: Aktualisieren Sie dieses Plugin oder geben Sie den Schlüssel erneut ein.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Der gespeicherte Schlüssel kann nicht mehr geöffnet werden (die Sicherheitsschlüssel der Website haben sich geändert). Geben Sie ihn erneut ein.','Not connected'=>'Nicht verbunden','Connected — last test passed %s'=>'Verbunden – letzter Test erfolgreich (%s)','Last test failed: %s'=>'Letzter Test fehlgeschlagen: %s','Connected — not tested yet'=>'Verbunden – noch nicht getestet','Which model to use'=>'Zu verwendendes Modell','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ kennzeichnet unsere Empfehlung für diese Aufgabe. Die Liste enthält jedes Modell, das Ihr Schlüssel verwenden kann, live vom Anbieter abgerufen.','— Recommended for the provider —'=>'— Vom Anbieter empfohlen —','Save models'=>'Modelle speichern','Refresh the model lists from the providers'=>'Modelllisten von den Anbietern aktualisieren','best quality'=>'Beste Qualität','lowest cost'=>'Günstigste','fastest'=>'Am schnellsten','Add a model yourself'=>'Eigenes Modell hinzufügen','A model came out today? Paste its exact name to use it straight away.'=>'Ein neues Modell ist heute erschienen? Fügen Sie den genauen Namen ein, um es sofort zu verwenden.','Model name'=>'Modellname','Add model'=>'Modell hinzufügen','Recommended models list'=>'Liste der empfohlenen Modelle','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Die Liste der empfohlenen Modelle konnte nicht überprüft werden, daher werden keine Empfehlungen angezeigt. Installieren Sie das Plugin neu oder aktivieren Sie unten tägliche Updates.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Die verwendete Liste wurde am %s veröffentlicht. Jedes Plugin-Update stellt eine neue bereit.','Also check Zinn Digital® once a day for an updated list.'=>'Prüfen Sie außerdem einmal täglich Zinn Digital®, um eine aktualisierte Liste zu erhalten.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Es wird lediglich eine einfache Download-Anfrage gesendet: kein Schlüssel, keine Site-Adresse, nichts über Ihre Inhalte. Die Liste ist signiert, und eine Liste, die die Signaturprüfung nicht besteht, wird ignoriert.','Last checked %1$s: %2$s.'=>'Zuletzt überprüft am %1$s: %2$s.','Save, and check now if turned on'=>'Speichern und jetzt prüfen, ob aktiviert','a newer list was installed'=>'eine neuere Liste wurde installiert','already up to date'=>'bereits auf dem neuesten Stand','the download failed the signature check and was ignored'=>'Der Download hat die Signaturprüfung nicht bestanden und wurde ignoriert','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® konnte nicht erreicht werden; die aktuelle Liste bleibt in Verwendung','turned off'=>'deaktiviert','Open'=>'Öffnen','Check their status page'=>'Statusseite prüfen','Open your billing page'=>'Rechnungsseite öffnen','Open your API keys page'=>'Öffnen Sie Ihre Seite für API-Schlüssel','Open the AI settings'=>'KI-Einstellungen öffnen','Sorry, you are not allowed to do that.'=>'Es tut uns leid, aber das ist Ihnen nicht gestattet.','Unknown provider.'=>'Unbekannter Anbieter.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Geben Sie die Adresse Ihres Dienstes ein, zum Beispiel http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Das sieht nicht nach einem API-Schlüssel aus. Kopieren Sie ihn erneut, ohne Leerzeichen.','Paste your API key first.'=>'Fügen Sie zuerst Ihren API-Schlüssel ein.','Key removed.'=>'Schlüssel entfernt.','Models saved.'=>'Modelle gespeichert.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Geben Sie den exakten Namen des Modells ein, zum Beispiel so, wie er in der Dokumentation des Anbieters steht.','Added %s. Choose it under "Which model to use".'=>'%s hinzugefügt. Wählen Sie es unter „Welches Modell verwendet werden soll“ aus.','Model removed.'=>'Modell entfernt.','Daily updates are off. The list that came with the plugin is used.'=>'Tägliche Aktualisierungen sind deaktiviert. Es wird die Liste verwendet, die mit dem Plugin geliefert wurde.','Checked: %s.'=>'Ausgewählt: %s.','Model lists refreshed.'=>'Modellisten aktualisiert.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Ihr KI-Schlüssel wurde von einer neueren Version eines Ihrer Plugins gespeichert. Aktualisieren Sie dieses Plugin oder geben Sie den Schlüssel in den KI-Einstellungen erneut ein.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Ihr gespeicherter KI-Schlüssel kann nicht mehr geöffnet werden (die Sicherheitsschlüssel der Website haben sich geändert). Geben Sie ihn in den KI-Einstellungen erneut ein.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'KI ist noch nicht eingerichtet. Fügen Sie in den KI-Einstellungen einen Schlüssel für einen KI-Anbieter hinzu.','No model is chosen for this task. Pick one in the AI settings.'=>'Für diese Aufgabe wurde kein Modell ausgewählt. Wählen Sie eines in den KI-Einstellungen aus.','That AI provider is not supported by this version of the plugin.'=>'Dieser KI-Anbieter wird von dieser Version des Plugins nicht unterstützt.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Diese Website konnte Ihren KI-Dienst nicht erreichen. Überprüfen Sie, ob er ausgeführt wird und seine Adresse von Ihrem Webserver aus erreichbar ist (ein Dienst auf Ihrem eigenen Computer ist von einer gehosteten Website aus nicht erreichbar).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Diese Website konnte %s nicht erreichen. Überprüfen Sie deren Statusseite; falls sie online ist, blockiert Ihr Host möglicherweise ausgehende Verbindungen oder die Adresse ist falsch.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s meldet, dass Ihr Konto über kein Guthaben und keine Quote mehr verfügt. Fügen Sie Guthaben hinzu oder erhöhen Sie Ihr Limit in Ihrem dortigen Konto und versuchen Sie es dann erneut.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s hat Ihren Schlüssel nicht akzeptiert. Er wurde möglicherweise falsch eingegeben, widerrufen oder ist abgelaufen. Erstellen Sie einen neuen Schlüssel und fügen Sie ihn hier ein.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s hat diese Anfrage für Ihren Schlüssel abgelehnt. Der Schlüssel hat möglicherweise keinen Zugriff auf dieses Modell oder diese Funktion, oder Ihr Konto muss verifiziert werden.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Das Modell „%1$s“ ist von %2$s für Ihren Schlüssel nicht verfügbar. Wählen Sie ein anderes Modell in den KI-Einstellungen.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Ihr Tarif %2$s beinhaltet nicht das Modell „%1$s“. Wählen Sie in den KI-Einstellungen ein anderes Modell aus oder führen Sie ein Upgrade Ihres Tarifs durch.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s begrenzt, wie schnell Ihr Schlüssel Anfragen senden kann. Warten Sie eine Minute und versuchen Sie es erneut, oder erhöhen Sie Ihr Rate-Limit bei diesem Anbieter.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s hat derzeit Probleme (ein Ausfall oder eine Überlastung auf deren Seite). An Ihren Einstellungen liegt es nicht. Versuchen Sie es in Kürze noch einmal.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Die KI-Anfrage ist aus einem nicht näher bestimmbaren Grund fehlgeschlagen. Versuchen Sie es erneut; sollte das Problem weiterhin auftreten, wenden Sie sich bitte unter Angabe der nachfolgenden Details an den Support.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Der KI-Anbieter hat in einem Format geantwortet, das dieses Plugin nicht lesen kann. Versuchen Sie es erneut. Sollte das Problem weiterhin bestehen, wählen Sie ein anderes Modell oder wenden Sie sich an den Support.','Custom (OpenAI-compatible)'=>'Benutzerdefiniert (OpenAI-kompatibel)','Save a key for this provider first.'=>'Speichern Sie zuerst einen Schlüssel für diesen Anbieter.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Ihr Schlüssel funktioniert, aber der Anbieter führt kein Textmodell dafür auf. Fügen Sie unten selbst ein Modell hinzu.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Verbunden. %1$s antwortete mit %2$s. Ihre KI-Funktionen sind einsatzbereit.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Ihre Benutzerrolle ist nicht berechtigt, KI auf dieser Website zu nutzen. Wenden Sie sich an einen Administrator.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Diese Website hat ihr monatliches KI-Ausgabenlimit erreicht. Ein Administrator kann es in den KI-Einstellungen erhöhen.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Diese Website hat ihr monatliches Limit für KI-Anfragen erreicht. Ein Administrator kann dieses in den KI-Einstellungen erhöhen.','Usage and cost'=>'Nutzung und Kosten','The log, limits and role permissions apply to AI used through: %s.'=>'Das Protokoll, die Limits und die Rollenberechtigungen gelten für KI, die genutzt wird über: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Die Kosten sind ungefähre Angaben, ermittelt anhand veröffentlichter Preise; ein Modell ohne bekannten Preis wird als null gewertet.','This month: %1$s requests, about %2$s.'=>'Diesen Monat: %1$s Anfragen, etwa %2$s.','When'=>'Wann','Who'=>'Wer','Used for'=>'Verwendet für','Model'=>'Modell','Tokens in / out'=>'Tokens ein / aus','About'=>'Über uns','Result'=>'Ergebnis','No AI requests have been made yet.'=>'Es wurden noch keine KI-Anfragen gestellt.','Done'=>'Fertig','Limits and permissions'=>'Limits und Berechtigungen','Monthly spending limit (US dollars)'=>'Monatliches Ausgabenlimit (US-Dollar)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Für kein Limit leer lassen. Die KI stoppt für den Rest des Monats, sobald die ungefähre Obergrenze erreicht ist.','Monthly request limit'=>'Monatliches Anfragelimit','Leave empty for no limit.'=>'Für kein Limit leer lassen.','Who may use AI'=>'Wer KI verwenden darf','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Wählen Sie keine Option aus, um allen Benutzern, die die Funktionen des Plugins verwenden können, die Nutzung von KI zu gestatten. Administratoren können sie immer verwenden.','Save limits and permissions'=>'Grenzwerte und Berechtigungen speichern','Limits and permissions saved.'=>'Limits und Berechtigungen gespeichert.','That language is not one of this site\'s languages.'=>'Diese Sprache gehört nicht zu den Sprachen dieser Website.','A translation must be the same kind of content as the original.'=>'Eine Übersetzung muss dieselbe Art von Inhalt sein wie das Original.','Choose one of the site\'s other languages.'=>'Wählen Sie eine der anderen Sprachen der Website.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Die Skripte des Administrationsbildschirms fehlen in dieser Kopie des Plugins. Installieren Sie es aus einem veröffentlichten Paket neu.','This screen needs JavaScript.'=>'Dieser Bildschirm erfordert JavaScript.','Choose a language'=>'Sprache auswählen','Upgrade'=>'Upgrade','Pricing'=>'Preise','Start Trial'=>'Testphase starten','Account'=>'Konto','Contact Us'=>'Kontaktieren Sie uns','Affiliation'=>'Affiliation','the kind of softwarePlugin'=>'Plugin','greetingHey %s,'=>'Hallo %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Melden Sie sich an, um E-Benachrichtigungen für Sicherheits- und Funktionsupdates, Bildungsinhalte und gelegentliche Angebote zu erhalten sowie einige grundlegende WordPress-Umgebungsinformationen zu teilen. Dies wird uns helfen, das %s kompatibler mit Ihrer Website zu machen und es besser an Ihre Bedürfnisse anzupassen.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Melden Sie sich an, um E-Mail-Benachrichtigungen für Sicherheits- und Funktionsupdates, Schulungsinhalte und gelegentliche Angebote zu erhalten sowie einige grundlegende WordPress-Umgebungsinformationen zu teilen.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Wenn Sie dies überspringen, ist das kein Problem! %1$s funktioniert trotzdem einwandfrei.','Allow & Continue'=>'Erlauben & Fortfahren','verbSkip'=>'Überspringen','Skipping, please wait'=>'Wird übersprungen, bitte warten','Continue'=>'Weiter','Please wait'=>'Bitte warten','as activating pluginActivating'=>'Wird aktiviert','This will allow %s to'=>'Dies ermöglicht %s','Privacy Policy'=>'Datenschutzerklärung','Terms of Service'=>'Nutzungsbedingungen','License Agreement'=>'Lizenzvereinbarung','Have a license key?'=>'Haben Sie einen Lizenzschlüssel?','Activate License'=>'Lizenz aktivieren','View Basic Profile Info'=>'Grundlegende Profilinformationen anzeigen','Your WordPress user\'s: first & last name, and email address'=>'Die folgenden Daten Ihres WordPress-Benutzers: Vor- und Nachname sowie E-Mail-Adresse','View Basic Website Info'=>'Grundlegende Website-Informationen anzeigen','Homepage URL & title, WP & PHP versions, and site language'=>'Homepage-URL und -Titel, WP- und PHP-Versionen sowie Website-Sprache','View Basic %s Info'=>'Erweiterte Basis-%s-Informationen anzeigen','Current %s & SDK versions, and if active or uninstalled'=>'Aktuelle %s- und SDK-Versionen sowie Status (aktiv oder deinstalliert)','Newsletter'=>'Newsletter','Updates, announcements, marketing, no spam'=>'Updates, Ankündigungen, Marketing, kein Spam','View Diagnostic Info'=>'Diagnoseinformationen anzeigen','WordPress & PHP versions, site language & title'=>'WordPress- & PHP-Versionen, Seitensprache & -titel','View Plugins & Themes List'=>'Liste der Plugins und Themes anzeigen','Names, slugs, versions, and if active or not'=>'Namen, Slugs, Versionen und Aktivierungsstatus','optional'=>'optional','Never miss an important update'=>'Verpassen Sie kein wichtiges Update','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Wir haben diese Option eingeführt, damit Sie keine wichtige Aktualisierung verpassen und uns dabei helfen, %s kompatibler mit Ihrer Website zu machen und Ihre Anforderungen noch besser zu erfüllen.','Thank you for updating to %1$s v%2$s!'=>'Vielen Dank für das Update auf %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Das Präfix muss aus 1 bis 8 Kleinbuchstaben oder Ziffern bestehen, mit einem Buchstaben beginnen und darf nicht den Namen des Plugins tragen.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'„%s“ ist kein Sprachcode. Verwenden Sie ein WordPress-Gebietsschema wie fr_FR oder de_DE.','List at least one language.'=>'Geben Sie mindestens eine Sprache an.','You are not allowed to translate this item.'=>'Sie sind nicht berechtigt, dieses Element zu übersetzen.','This item already has a version in that language.'=>'Dieser Artikel ist bereits in dieser Sprache verfügbar.','That translation engine is not available on this site.'=>'Diese Übersetzungsengine ist auf dieser Website nicht verfügbar.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'Verschiedene Engines je Sprache, automatisches Fallback und Ausgabenlimits sind Tranzly Pro-Funktionen.','Each language must be one of the site\'s languages, with an available engine.'=>'Jede Sprache muss eine der Sprachen der Website sein und über eine verfügbare Engine verfügen.','The fallback list may only name available engines.'=>'Die Ausweichliste darf nur verfügbare Engines benennen.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'Ein monatliches Limit ist ein Betrag in US-Dollar, gleich null oder mehr, für eine verfügbare Engine.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'Bevorzugte Übersetzungen und Töne nach Sprache sind Tranzly Pro-Funktionen. Die Liste der nicht zu übersetzenden Begriffe ist kostenlos.','Glossary entries must be grouped by one of the site\'s languages.'=>'Glossarträge müssen nach einer der Website-Sprachen gruppiert werden.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'Der Ton wird pro Website-Sprache festgelegt: Standard-Höhegrad, mehr oder weniger, plus optionale Anweisungen.','The value for %s is not one of the allowed choices.'=>'Der Wert für %s gehört nicht zu den zulässigen Auswahlmöglichkeiten.','The background queue is not available on this site.'=>'Die Hintergrundwarteschlange ist auf dieser Website nicht verfügbar.','A translation job runs as the person who starts it, so a user must be signed in.'=>'Ein Übersetzungsauftrag wird unter der Kennung der Person ausgeführt, die ihn startet, daher muss ein Benutzer angemeldet sein.','There is nothing you are allowed to translate in that selection.'=>'In dieser Auswahl gibt es nichts, was Sie übersetzen dürfen.','That item is not part of a translation job.'=>'Dieser Artikel ist nicht Teil eines Übersetzungsauftrags.','You are not allowed to change that translation.'=>'Sie sind nicht berechtigt, diese Übersetzung zu ändern.','This item\'s group already has a %1$s version (#%2$d).'=>'Die Gruppe dieses Elements hat bereits eine %1$s-Version (#%2$d).','An item cannot be its own translation.'=>'Ein Element kann nicht seine eigene Übersetzung sein.','That item is already a translation of something else. Unlink it first.'=>'Dieser Eintrag ist bereits eine Übersetzung von etwas anderem. Trennen Sie zuerst die Verknüpfung.','The translation link could not be saved.'=>'Der Übersetzungslink konnte nicht gespeichert werden.','That text cannot be translated here.'=>'Dieser Text kann hier nicht übersetzt werden.','That media text cannot be translated here.'=>'Dieser Medientext kann hier nicht übersetzt werden.','A translation can be published or kept as a draft.'=>'Eine Übersetzung kann veröffentlicht oder als Entwurf gespeichert werden.','You are not allowed to publish this kind of content.'=>'Sie sind nicht berechtigt, diese Art von Inhalt zu veröffentlichen.','This item is already written in that language.'=>'Dieser Artikel ist bereits in dieser Sprache verfasst.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Diese Übersetzung wurde von einer Person bearbeitet (oder importiert) und ist daher geschützt. Entsperren Sie sie, um sie erneut zu übersetzen.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Es ist noch keine Übersetzungsmaschine eingerichtet. Fügen Sie unter Tranzly → Engines einen Schlüssel für eine hinzu.','That translation engine is not set up yet: add its key first.'=>'Diese Übersetzungssuchmaschine ist noch nicht eingerichtet: Fügen Sie zuerst ihren Schlüssel hinzu.','The same text is being translated by another job right now; this item will use that answer.'=>'Der derselbe Text wird gerade von einem anderen Auftrag übersetzt; für diesen Eintrag wird diese Antwort verwendet.','No translation engine could take this item.'=>'Keine Übersetzungssuchmaschine konnte dieses Element verarbeiten.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'Die Engine hat für diesen Eintrag nicht für jeden Teil eine Übersetzung zurückgegeben. Es wurde nichts geändert.','AI model'=>'KI-Modell','AI model (%1$s %2$s)'=>'KI-Modell (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'%s hat zurzeit Probleme. Versuchen Sie es in Kürze noch einmal oder verwenden Sie eine andere Suchmaschine.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'Ihre Website konnte %s nicht erreichen. Stellen Sie sicher, dass sie ausgehende Verbindungen herstellen kann, und versuchen Sie es dann erneut.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'%s hat Ihren API-Schlüssel nicht akzeptiert. Überprüfen Sie den Schlüssel in Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'Ihr %s-Konto hat sein Kontingent oder Guthaben aufgebraucht. Laden Sie es bei diesen auf oder verwenden Sie eine andere Engine.','%s asked us to slow down. It will be tried again automatically.'=>'%s hat uns gebeten, langsamer zu verfahren. Es wird automatisch erneut versucht.','This text is too long for %s in one go. Split the content, or use another engine.'=>'Dieser Text ist für %s auf einmal zu lang. Teilen Sie den Inhalt auf oder verwenden Sie eine andere Engine.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'%s hat die Übersetzung dieses Inhalts verweigert. Versuchen Sie es mit einer anderen Engine oder übersetzen Sie es manuell.','%s does not translate this language. Choose another engine for it.'=>'%s übersetzt diese Sprache nicht. Wählen Sie eine andere Engine dafür.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'Das Ausgabenlimit dieses Monats für %s ist erreicht, daher wurden keine weiteren Daten dorthin gesendet. Erhöhen Sie das Limit in Tranzly → Engines oder warten Sie bis zum nächsten Monat.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'Die Übersetzung mit %s ist aus einem Grund fehlgeschlagen, den Tranzly nicht ermitteln konnte. Die Details finden Sie unten.','An engine id must be lowercase letters, digits and hyphens.'=>'Eine Engine-ID darf nur aus Kleinbuchstaben, Ziffern und Bindestrichen bestehen.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Erstellt von Neil Lock, CEO von Zinn Digital® Ltd','Version %s'=>'Version %s','Tranzly website'=>'Tranzly-Website','Zinn Digital® website'=>'Zinn Digital®-Website','Settings saved.'=>'Einstellungen gespeichert.','See the Pro plans and pricing'=>'Sehen Sie sich die Pro-Tarife und Preise an','Languages'=>'Sprachen','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Die erste Sprache ist die, in der Ihr Inhalt verfasst ist. Besucher wechseln über den Sprachumschalter-Block.','(default)'=>'(Standard)','Locale code'=>'Gebietsschema-Code','For example fr_FR'=>'Zum Beispiel fr_FR','Name (optional)'=>'Name (optional)','For example Français'=>'Zum Beispiel Français','Add language'=>'Sprache hinzufügen','Front-end output'=>'Frontend-Ausgabe','Class name prefix'=>'Klassennamen-Präfix','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Jeder Klassenname, den das Plugin auf Ihren Seiten ausgibt, beginnt mit diesem Präfix, damit die Seiten nicht verraten, welches Plugin sie erstellt hat. 1 bis 8 Kleinbuchstaben oder Ziffern, beginnend mit einem Buchstaben.','Beta updates'=>'Beta-Updates','This site receives beta versions as updates.'=>'Diese Website erhält Beta-Versionen als Updates.','This site receives stable versions only.'=>'Diese Website erhält ausschließlich stabile Versionen.','Change this on the Account page'=>'Ändern Sie dies auf der Kontoseite','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Beta-Versionen werden für lizenzierte Pro-Installationen angeboten, die mit ihrem Konto verbunden sind. Nach der Verbindung können Sie über die Kontoseite beitreten.','Save settings'=>'Einstellungen speichern','First engine that is set up'=>'Erster eingerichteter Motor','Key saved. It is stored encrypted and never shown again.'=>'Schlüssel gespeichert. Er wird verschlüsselt gespeichert und nie wieder angezeigt.','Engine settings saved.'=>'Motoreinstellungen gespeichert.','Glossary saved.'=>'Glossar gespeichert.','Your keys'=>'Ihre Schlüssel','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'Tranzly ruft die Übersetzungsdienste über Ihr eigenes Konto auf. Die Schlüssel werden verschlüsselt in Ihrer Datenbank gespeichert und ausschließlich an den Dienst gesendet, zu dem sie gehören. Die Schlüssel für die KI-Modelle werden in den KI-Einstellungen festgelegt.','%s API key'=>'%s API-Schlüssel','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'Gespeichert: %s. Geben Sie einen neuen Schlüssel ein, um ihn zu ersetzen, oder speichern Sie ein leeres Feld, um ihn zu entfernen.','No key saved.'=>'Kein Schlüssel gespeichert.','Azure region (leave empty for a global resource)'=>'Azure-Region (für eine globale Ressource leer lassen)','Save key'=>'Schlüssel speichern','Check my DeepL usage'=>'DeepL-Nutzung prüfen','%1$s of %2$s characters used this billing period.'=>'%1$s von %2$s Zeichen in diesem Abrechnungszeitraum verwendet.','Which engine translates'=>'Welche Engine übersetzt','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'Es ist noch keine Engine eingerichtet. Speichern Sie oben einen Schlüssel (oder richten Sie ein KI-Modell ein), um mit der Übersetzung zu beginnen.','Default engine'=>'Standard-Engine','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'Ein unterschiedlicher Übersetzungsdienst pro Sprache, automatisches Fallback und monatliche Ausgabenlimits sind Tranzly Pro-Funktionen.','Engine for %s'=>'Engine für %s','The default engine'=>'Die Standard-Engine','If an engine fails or reaches a limit, try these next, in this order'=>'Wenn ein Motor ausfällt oder ein Limit erreicht, versuchen Sie nacheinander Folgendes in dieser Reihenfolge:','Monthly spending caps'=>'Monatliche Ausgabenlimits','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'Wenn eine Engine ihr Limit erreicht, wird bis zum nächsten Monat nichts mehr an sie gesendet, und der Bericht über fehlgeschlagene Übersetzungen gibt den Grund dafür an. Leer lassen für kein Limit.','%1$s (spent this month: $%2$s)'=>'%1$s (diesen Monat ausgegeben: $%2$s)','Save caps'=>'Obergrenzen speichern','Glossary and words never translated'=>'Glossary und niemals übersetzte Wörter','Never translate these words (one per line)'=>'Diese Wörter niemals übersetzen (eines pro Zeile)','Brand and product names stay exactly as they are, with every engine.'=>'Marken- und Produktnamen bleiben bei jeder Engine exakt so, wie sie sind.','Preferred translations and tone per language are Tranzly Pro features.'=>'Bevorzugte Übersetzungen und Tonalität pro Sprache sind Tranzly Pro-Funktionen.','Preferred translations (one per line: term = translation)'=>'Bevorzugte Übersetzungen (eine pro Zeile: Begriff = Übersetzung)','Formality'=>'Formalität','Default'=>'Standard','Formal'=>'Formell','Informal'=>'Informell','Style instructions (audience, brand voice)'=>'Stilanweisungen (Zielgruppe, Markenstimme)','Save glossary'=>'Glossar speichern','Job started with %d translations to do. It runs in the background: you can close this page.'=>'Der Job wurde mit %d auszuführenden Übersetzungen gestartet. Er läuft im Hintergrund: Sie können diese Seite schließen.','Queued again.'=>'Erneut in der Warteschlange.','Running'=>'Wird ausgeführt','Finished'=>'Abgeschlossen','Cancelled'=>'Gekündigt','Translate in the background'=>'Im Hintergrund übersetzen','Set up a translation engine in the Engines tab first.'=>'Richten Sie zuerst eine Übersetzungs-Engine im Tab „Engines“ ein.','Translate every'=>'Jeden übersetzen','Into'=>'In','With'=>'Mit','Each language’s own engine'=>'Die Suchmaschine jeder Sprache','Publish the translations (otherwise they are saved as drafts)'=>'Veröffentlichen Sie die Übersetzungen (sonst werden sie als Entwürfe gespeichert)','Estimate the cost'=>'Kosten berechnen','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d Beiträge, %2$s Zeichen. Der Preis für diese Engine ist im Voraus nicht bekannt.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d Beiträge, %2$s Zeichen: ca. $%3$s über Ihr eigenes Konto.','Start translating'=>'Mit der Übersetzung beginnen','Jobs'=>'Jobs','No translation jobs yet.'=>'Keine Übersetzungsaufträge vorhanden.','Job %1$d — %2$s'=>'Job %1$d — %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'%1$d von %2$d übersetzt, %3$d fehlgeschlagen, %4$d übersprungen (geschützt oder bereits in dieser Sprache)','Stop this job'=>'Diesen Job stoppen','See what failed and why'=>'Sehen Sie, was fehlgeschlagen ist, und warum','Content'=>'Inhalt','Language'=>'Sprache','What went wrong'=>'Was ist schiefgelaufen','Fix it'=>'Beheben','Details'=>'Details','Retry with'=>'Erneut versuchen mit','The same engine'=>'Dieselbe Engine','Retry'=>'Wiederholen','Translate by hand'=>'Manuell übersetzen','Languages and settings'=>'Sprachen und Einstellungen','Engines'=>'Engines','Translation jobs'=>'Übersetzungsaufträge','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Fügen Sie im Admin-Menü unter Tranzly eine zweite Sprache hinzu, und der Umschalter erscheint hier.','Switcher'=>'Umschalter','Accessible label'=>'Barrierefreies Label','block titleLanguage switcher'=>'Sprachumschalter','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Links zu dieser Seite in jeder Sprache der Website. Es wird nichts angezeigt, bis zwei oder mehr Sprachen aufgelistet sind.','block keywordlanguage'=>'Sprache','block keywordswitcher'=>'Wechsler','block keywordtranslation'=>'Übersetzung']];